// Glass Editorial 4:3 native Google Slides generator.
// Input: source presentation resource from Slides API; output: one batchUpdate array per slide.
// Keep the source presentation JSON and research content outside this public repository.
// Assets are generated by render_glass.py. Upload them using the Slides connector sidecar,
// or replace the local asset URLs with authenticated, temporary HTTPS image URLs.
export function buildDeck(source, assetDir="assets") {
const C={paper:"#F2F4EF",white:"#FCFDF9",ink:"#202C2A",muted:"#53645F",sage:"#A4B7A0",green:"#315D50",mint:"#D9E5D8",plum:"#6A547D",lilac:"#E4DFEA",gold:"#A38059",sand:"#EDE3D2",dark:"#1C3733",gray:"#D7DFDA"};
const rgb=h=>({red:parseInt(h.slice(1,3),16)/255,green:parseInt(h.slice(3,5),16)/255,blue:parseInt(h.slice(5,7),16)/255});
let req=[],seq=0,sid,images=[];const uid=()=>`g_${sid}_${++seq}`;
const ep=(x,y,w,h)=>({pageObjectId:sid,size:{width:{magnitude:Math.max(w,1),unit:"PT"},height:{magnitude:Math.max(h,1),unit:"PT"}},transform:{scaleX:1,scaleY:1,translateX:x,translateY:y,unit:"PT"}});
function box(x,y,w,h,fill,shape="RECTANGLE",alpha=1,outline=null){const o=uid();req.push({createShape:{objectId:o,shapeType:shape,elementProperties:ep(x,y,w,h)}});req.push({updateShapeProperties:{objectId:o,shapeProperties:{shapeBackgroundFill:{solidFill:{color:{rgbColor:rgb(fill)},alpha}},outline:outline?{outlineFill:{solidFill:{color:{rgbColor:rgb(outline)},alpha:1}},weight:{magnitude:1,unit:"PT"}}:{propertyState:"NOT_RENDERED"}},fields:"shapeBackgroundFill,outline"}});return o}
function txt(t,x,y,w,h,fs=14,bold=false,color=C.ink,align="START"){if(!t)return;const o=uid();req.push({createShape:{objectId:o,shapeType:"TEXT_BOX",elementProperties:ep(x,y,w,h)}},{insertText:{objectId:o,text:t}},{updateTextStyle:{objectId:o,textRange:{type:"ALL"},style:{fontFamily:"Arial",fontSize:{magnitude:fs,unit:"PT"},bold,foregroundColor:{opaqueColor:{rgbColor:rgb(color)}}},fields:"fontFamily,fontSize,bold,foregroundColor"}},{updateParagraphStyle:{objectId:o,textRange:{type:"ALL"},style:{alignment:align,lineSpacing:100,spaceAbove:{magnitude:0,unit:"PT"},spaceBelow:{magnitude:0,unit:"PT"}},fields:"alignment,lineSpacing,spaceAbove,spaceBelow"}});return o}
function glass(x,y,w,h,col){box(x+w*.1,y+h*.75,w*.88,h*.25,C.dark,"ELLIPSE",.12);box(x,y,w,h,col,"ELLIPSE",.9,C.white);box(x+w*.08,y+h*.08,w*.84,h*.81,C.white,"ELLIPSE",.28,C.white);box(x+w*.16,y+h*.15,w*.62,h*.18,C.white,"ELLIPSE",.67);box(x+w*.48,y+h*.55,w*.40,h*.29,C.green,"ELLIPSE",.18)}
function asset(name,x,y,w,h){const url=assetDir+"/"+name+".png";images.push(url);req.push({createImage:{objectId:uid(),url,elementProperties:ep(x,y,w,h)}})}
function bg(fill){req.push({updatePageProperties:{objectId:sid,pageProperties:{pageBackgroundFill:{solidFill:{color:{rgbColor:rgb(fill)},alpha:1}}},fields:"pageBackgroundFill"}})}
function panel(x,y,w,h,fill=C.white){box(x+2,y+3,w,h,C.gray,"ROUND_RECTANGLE",.65);box(x,y,w,h,fill,"ROUND_RECTANGLE")}
function header(a){txt(a[0],25,15,670,25,11,true,C.green);txt(a[1],25,40,670,70,a[1].length>53?24:28,true);txt(a[2],25,107,670,40,13,false,C.muted)}
function pair(h,b,x,y,w,height,fill=C.white){panel(x,y,w,height,fill);txt(h,x+8,y+6,w-16,46,16,true,C.green);txt(b,x+8,y+55,w-16,height-58,13)}
function note(t,y=450){panel(25,y,670,48,C.mint);txt(t,31,y+2,658,47,t?.length>140?11.7:13,true)}
const textof=e=>e.shape?.text?.textElements?.map(t=>t.textRun?.content??"").join("").trimEnd()??"";
const T=source.slides.map(s=>s.pageElements.map(textof).filter(t=>t.trim()));
const stripped=T.map(t=>t.filter((v,j)=>!(j<5&&/^\d{2}$/.test(v))));
function sourceMap(s){const scale=.75;let k=0;for(const e of s.pageElements){const t=textof(e),tr=e.transform??{},sz=e.size??{},x=(tr.translateX??0)/12700*scale,y=(tr.translateY??0)/12700,w=(sz.width?.magnitude??0)*(tr.scaleX??1)/12700*scale,h=(sz.height?.magnitude??0)*(tr.scaleY??1)/12700;if(w<1||h<1)continue;
 if(e.image){if(w>600&&h>400)continue;glass(x,y,w,h,[C.sage,C.plum,C.gold][k++%3]);continue}
 if(e.line||!e.shape)continue;
 if(t&&/^\d{2}$/.test(t)&&y>495)continue;
 const oldFill=e.shape.shapeProperties?.shapeBackgroundFill,old=oldFill?.solidFill?.color?.rgbColor;
 if(oldFill?.propertyState!=="NOT_RENDERED"&&old&&!t){let avg=((old.red??0)+(old.green??0)+(old.blue??0))/3,fill=avg>.94?C.white:avg>.72?C.mint:avg>.48?C.sage:avg>.28?C.green:C.dark;let typ=e.shape.shapeType==="ELLIPSE"?"ELLIPSE":e.shape.shapeType==="ROUND_RECTANGLE"?"ROUND_RECTANGLE":"RECTANGLE";box(x,y,w,h,fill,typ,oldFill.solidFill?.alpha??1);continue}
 if(t){let st=e.shape.text.textElements.find(z=>z.textRun)?.textRun?.style??{},f=st.fontSize?.magnitude??14,bold=st.bold??false,col=C.ink,oldc=st.foregroundColor?.opaqueColor?.rgbColor;if(oldc&&(oldc.red??0)>.9&&(oldc.green??0)>.9&&(oldc.blue??0)>.9)col=C.white;else if(bold)col=C.green;txt(t,x-3,y-2,w+7,h+7,Math.max(7,f*.81),bold,col,e.shape.text.textElements.find(z=>z.paragraphMarker)?.paragraphMarker?.style?.alignment??"START")}
}}
const batches=[];
for(let i=0;i<source.slides.length;i++){sid=`glass_page_${String(i+1).padStart(2,"0")}`;seq=0;req=[];images=[];req.push({createSlide:{objectId:sid,slideLayoutReference:{predefinedLayout:"BLANK"}}});bg(C.paper);let a=stripped[i],n=i+1;
if(n===1){bg(C.dark);txt(a[0],24,25,655,27,14,true,C.mint);txt(a[1],25,85,470,78,48,true,C.white);txt(a[2],25,173,420,134,22,true,C.white);txt(a[3],25,345,425,35,20,true,C.white);txt(a[4],25,383,427,76,13,false,C.mint);txt(a[5],25,480,420,32,12,false,C.mint);for(let j=6;j<9;j++)txt(a[j],477,395+(j-6)*31,200,31,16,true,C.white);asset("torus",390,26,330,330)}
else if(n===2){header(a);panel(25,152,245,337,C.sand);txt(a[4],36,292,223,104,19,true);txt(a[5],36,404,222,77,13,false,C.muted);asset("molecule",49,145,185,153);for(let j=0;j<3;j++){let y=150+j*112;asset(["breath","cold","molecule"][j],275,152+j*112,85,85);txt(a[6+j*2],362,y,330,47,15.5,true,C.green);txt(a[7+j*2],362,y+47,330,64,13)}txt(a[3],25,506,670,26,9,false,C.muted)}
else if(n===3){header(a);for(let j=0;j<4;j++){let x=25+(j%2)*340,y=151+Math.floor(j/2)*139;panel(x,y,330,131,[C.mint,C.white,C.lilac,C.white][j]);asset(["breath","cold","torus","molecule"][j],x+3,y+20,94,94);txt(a[4+j*2],x+88,y+7,231,37,17,true,C.green);txt(a[5+j*2],x+88,y+45,231,82,13)}note(a[12],438);txt(a[3],25,507,670,24,9,false,C.muted)}
else if(n===4){header(a);panel(25,151,330,340,C.mint);panel(365,151,330,340,C.lilac);txt(a[4],32,160,315,42,25,true,C.green);txt(a[5],32,207,315,39,14);txt(a[6],32,252,315,34,17,true);txt(a[7],32,291,315,90,15);txt(a[8],32,390,315,85,15,true);txt(a[9],372,160,315,42,25,true,C.plum);txt(a[10],372,207,315,59,14);txt(a[11],372,273,315,115,23,true,C.plum);txt(a[12],372,398,315,77,13);txt(a[3],25,507,670,24,8.5,false,C.muted)}
else if(n===5){header(a);for(let j=0;j<3;j++){let x=25+j*226;panel(x,151,218,278,[C.mint,C.white,C.lilac][j]);txt(a[4+j*4],x+7,160,204,54,32,true,j===2?C.plum:C.green);txt(a[5+j*4],x+7,218,204,49,14,true);txt(a[6+j*4],x+7,273,204,46,13);txt(a[7+j*4],x+7,323,204,102,12.5)}note(a[16],439);txt(a[3],25,506,670,25,8.5,false,C.muted)}
else if(n===6){bg(C.dark);txt(a[0],25,18,670,26,12,true,C.mint);txt(a[1],25,45,670,65,35,true,C.white);txt(a[2],25,120,480,199,21,true,C.white);pair(a[3],a[4],25,329,330,174,C.mint);pair(a[5],a[6],365,329,330,174,C.lilac);asset("molecule",492,88,220,220)}
else if(n===7){header(a);txt(a[3],25,147,670,65,14,true);for(let j=0;j<4;j++){let x=25+(j%2)*340,y=216+Math.floor(j/2)*147;pair(a[4+j*2],a[5+j*2],x,y,330,138,[C.white,C.mint,C.sand,C.lilac][j])}}
else if(n===8){header(a);panel(25,150,382,354,C.white);panel(417,150,278,354,C.mint);txt(a[3],32,158,368,41,16,true,C.green);for(let j=0;j<4;j++){let y=202+j*72;txt(a[4+j*2],32,y,368,25,14,true);txt(a[5+j*2],32,y+27,368,43,12.5,false,C.muted)}txt(a[12],424,158,264,48,17,true,C.green);txt(a[13],424,211,264,55,15,true);txt(a[14],424,270,264,30,14);txt(a[15],424,310,264,62,15,true);txt(a[16],424,374,264,30,14);txt(a[17],424,425,264,54,14,true,C.green)}
else if(n===9){header(a);for(let j=0;j<4;j++){let x=25+(j%2)*340,y=151+Math.floor(j/2)*175;pair(a[3+j*2],a[4+j*2],x,y,330,166,[C.white,C.mint,C.lilac,C.white][j])}}
else if(n===10){header(a);for(let j=0;j<4;j++){let x=25+(j%2)*340,y=151+Math.floor(j/2)*62;panel(x,y,330,55,j%2?C.lilac:C.mint);txt(a[3+j],x+5,y+2,320,52,13.5,true)}for(let j=0;j<2;j++)pair(a[7+j*2],a[8+j*2],25+j*340,284,330,217,j?C.sand:C.white)}
else if(n>=11&&n<=18){sourceMap(source.slides[i])}
else {bg(C.dark);txt(a[0],25,180,475,180,42,true,C.white);asset("torus",380,38,340,340)}
batches.push({requests:req,image_uris:images})}
return batches}
